const s = $json;

const valid =
  /^MILO-[0-9]{3}$/.test(s.storyId ?? '') &&
  s.scriptId === `${s.storyId}-S01` &&
  s.outlineId === `${s.storyId}-O01` &&
  /^MILO-[0-9]{3}-C0[1-3]$/.test(s.conceptId ?? '') &&
  (s.conceptId ?? '').startsWith(`${s.storyId}-`) &&
  s.approvalStatus === 'APPROVED' &&
  String(s.approvalProcessedAt ?? '').trim() !== '' &&
  String(s.scriptText ?? '').trim() !== '' &&
  Number(s.version) >= 1;

return {
  json: {
    ...s,
    valid
  }
};

const r = $json.output ?? $json;

const findings = Array.isArray(r.findings) ? r.findings : [];

const blockerCount = findings.filter(f => f.severity === 'BLOCKER').length;
const warningCount = findings.filter(f => f.severity === 'WARNING').length;
const infoCount = findings.filter(f => f.severity === 'INFO').length;

const expectedResult =
  blockerCount > 0
    ? 'FAIL'
    : warningCount > 0
      ? 'REVIEW_REQUIRED'
      : 'PASS';

const valid =
  /^MILO-[0-9]{3}$/.test(r.storyId ?? '') &&
  r.scriptId === `${r.storyId}-S01` &&
  ['PASS', 'REVIEW_REQUIRED', 'FAIL'].includes(r.assessmentResult) &&
  typeof r.summary === 'string' &&
  r.summary.trim() !== '' &&
  Number(r.blockerCount) === blockerCount &&
  Number(r.warningCount) === warningCount &&
  Number(r.infoCount) === infoCount &&
  r.assessmentResult === expectedResult &&
  findings.every((f, index) =>
    f.findingId &&
    f.category &&
    ['BLOCKER', 'WARNING', 'INFO'].includes(f.severity) &&
    f.title &&
    f.explanation &&
    f.scriptEvidence &&
    f.canonReference &&
    f.recommendedAction
  );

return {
  json: {
    ...r,
    continuityReviewValid: valid
  }
};

const stories = $input.all().map((item, inputIndex) => ({ item, inputIndex }));
const scripts = $('Validate Approved Script').all()
  .map((item, inputIndex) => ({ item, inputIndex }))
  .filter(({ item }) => item.json?.valid === true)
  .sort((a, b) => {
    const aRow = Number(a.item.json.row_number);
    const bRow = Number(b.item.json.row_number);
    const aHasRow = Number.isFinite(aRow);
    const bHasRow = Number.isFinite(bRow);
    if (aHasRow && bHasRow && aRow !== bRow) return aRow - bRow;
    if (aHasRow !== bHasRow) return aHasRow ? -1 : 1;
    const storyOrder = String(a.item.json.storyId ?? '').localeCompare(String(b.item.json.storyId ?? ''));
    return storyOrder || a.inputIndex - b.inputIndex;
  });

const storiesById = new Map();
for (const entry of stories) {
  const storyId = String(entry.item.json?.storyId ?? '').trim();
  if (!storyId) continue;
  const matches = storiesById.get(storyId) ?? [];
  matches.push(entry);
  storiesById.set(storyId, matches);
}

const classifyCandidate = ({ item, inputIndex }) => {
  const script = item.json;
  const storyId = String(script.storyId ?? '').trim();
  const matches = storiesById.get(storyId) ?? [];

  if (matches.length !== 1) {
    return {
      inputIndex,
      outcome: 'INTEGRITY_FAILURE',
      story: matches[0]?.item.json ?? { storyId },
      storyInputIndex: matches[0]?.inputIndex ?? 0,
      script,
      errorCode: 'APPROVED_SCRIPT_INVALID',
      message: matches.length === 0
        ? 'Processed approved Script does not resolve to a Story.'
        : 'Processed approved Script resolves to multiple Story rows.'
    };
  }

  const story = matches[0].item.json;
  const marker = String(story.canonInitializationState ?? '').trim();
  const storyVersion = String(story.canonVersion ?? '').trim();
  const storyRef = String(story.canonRef ?? '').trim();
  const scriptVersion = String(script.canonVersion ?? '').trim();
  const scriptRef = String(script.canonRef ?? '').trim();
  const storyBlank = storyVersion === '' && storyRef === '';
  const scriptBlank = scriptVersion === '' && scriptRef === '';
  const storyValid = /^canon-v[0-9]+\.[0-9]+$/.test(storyVersion) && /^[0-9a-f]{40}$/i.test(storyRef);
  const scriptValid = /^canon-v[0-9]+\.[0-9]+$/.test(scriptVersion) && /^[0-9a-f]{40}$/i.test(scriptRef);
  const lineageMatches = scriptVersion === storyVersion && scriptRef.toLowerCase() === storyRef.toLowerCase();

  if (marker === '' && storyBlank && scriptBlank) {
    return { inputIndex, outcome: 'PRE_CANON_LEGACY', story, storyInputIndex: matches[0].inputIndex, script };
  }

  if (!storyValid || !scriptValid || (marker !== '' && marker !== 'ASSIGNED')) {
    return {
      inputIndex,
      outcome: 'INTEGRITY_FAILURE',
      story,
      storyInputIndex: matches[0].inputIndex,
      script,
      errorCode: 'CANON_LINEAGE_INVALID',
      message: 'Processed approved Script or authoritative Story canon initialization marker/lineage is malformed. Continuity review was not attempted.'
    };
  }

  if (!lineageMatches) {
    return {
      inputIndex,
      outcome: 'INTEGRITY_FAILURE',
      story,
      storyInputIndex: matches[0].inputIndex,
      script,
      errorCode: 'CANON_LINEAGE_MISMATCH',
      message: 'Processed approved Script canon lineage conflicts with the authoritative Story. Continuity review was not attempted.'
    };
  }

  return {
    inputIndex,
    outcome: story.status === 'SCRIPT_APPROVED' ? 'ELIGIBLE' : 'INELIGIBLE',
    story,
    storyInputIndex: matches[0].inputIndex,
    script
  };
};

const classified = scripts.map(classifyCandidate);
const selected =
  classified.find((candidate) => candidate.outcome === 'ELIGIBLE') ??
  classified.find((candidate) => candidate.outcome === 'INTEGRITY_FAILURE');

if (!selected) return [];

const eligible = selected.outcome === 'ELIGIBLE';
return [{
  json: {
    ...selected.story,
    selectedScript: selected.script,
    continuityScriptEligible: eligible,
    continuityScriptCandidateOutcome: selected.outcome,
    errorCode: eligible ? '' : selected.errorCode,
    message: eligible ? '' : selected.message,
    scriptId: selected.script.scriptId ?? '',
    outlineId: selected.script.outlineId ?? '',
    conceptId: selected.script.conceptId ?? '',
    selectionFailureNode: 'Select Eligible Continuity Script',
    selectionFailureNodeType: 'n8n-nodes-base.code'
  },
  pairedItem: { item: selected.storyInputIndex }
}];

const story = $json;
const script = $('Select Eligible Continuity Script').first().json.selectedScript;
const canonVersion = String(story.canonVersion ?? '').trim();
const canonRef = String(story.canonRef ?? '').trim();
const storyValid = /^canon-v[0-9]+\.[0-9]+$/.test(canonVersion) && /^[0-9a-f]{40}$/i.test(canonRef);
const scriptVersion = String(script.canonVersion ?? '').trim();
const scriptRef = String(script.canonRef ?? '').trim();
const downstreamMatches = scriptVersion === canonVersion && scriptRef.toLowerCase() === canonRef.toLowerCase();
const canonLineageValid = storyValid && downstreamMatches;

return {
  json: {
    ...story,
    canonVersion,
    canonRef,
    canonLineageValid,
    errorCode: !storyValid ? 'CANON_LINEAGE_INVALID' : (downstreamMatches ? '' : 'CANON_LINEAGE_MISMATCH'),
    message: !storyValid
      ? 'Authoritative Story canonVersion/canonRef is blank or invalid. Canon retrieval was not attempted.'
      : (downstreamMatches ? '' : 'Approved Script canon lineage does not match the authoritative Story. Canon retrieval was not attempted.')
  }
};
